#  Section: Converts -trj folder into xtc for downstream analysis 
#  Author : Menzi Sikakane
""" This script's intended use is to convert the binary trajectory files generated by Desmond to XTC, which is the data type
that can be read by MDAnalysis.

# This is the backbone of script to the downstream analysis of MD simulation.
# How it works?
# 1. Desmond saves a trajectory as a FOLDER (ending in "_trj") full of
#    binary frame files. We tell MDTraj where that folder is.
# 2. A trajectory only holds coordinates (x, y, z of every atom per frame).
#    It does NOT say which atom is which, so we also need a topology file
#    (a PDB). Export one from Maestro, or from the "-out.cms" file.
# 3. MDTraj reads the Desmond folder, then writes the same frames as an
#    .xtc file. MDAnalysis can then open it together with the PDB.
#
# Install once:   pip install mdtraj
# Run:            python trj2xtc.py
"""

import mdtraj as md
Conversion = "_trj to .xtc"

print(f"   — {Conversion}")
traj = md.load(
    "desmond_md_trj/clickme.dtr", # Use the .dtr file from the -trj folder as input
    top=".pdb" # Use the same PDB/GRO file as topology reference
)

print(f"Loaded {traj.n_frames} frames, {traj.n_atoms} atoms")
traj.save_xtc("_trajectory.xtc") # Save as .xtc for use in DCCM, dPCA, and FEL scripts
print("Saved: _trajectory.xtc")
